content.content:
# Import people: a person per line of name,grade,terms,contact, in order. One change: every line is
# checked by the person form's rules before anything is written (a name or contact repeated within the
# import refuses it too), so a refused line refuses the whole import. A bad line is a 400, a name or
# contact already in use a 409.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateImportPeople
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: add
# Checks every line, then saves and audits each person (PERSON_ADDED, then its ROLLUP lines) in order.
add:
  class: net.officefloor.hq.app.person.AddImportedPeople
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithImportPeople
  govern: [ transaction ]
package net.officefloor.hq.app.person;

/**
 * People pasted into the import box as the screen sends them: one person per line, as
 * {@code name,grade,terms,contact}. The terms and contact may be absent or blank.
 */
public record ImportPeopleRequest(String text) {
}
package net.officefloor.hq.app.person;

import java.util.List;

/** The imported lines, each checked by the person form's rules, in the order they were pasted. */
public record ImportPeopleLines(List<PersonRequest> lines) {
}
package net.officefloor.hq.app.person;

/** How many people the import added. */
public record ImportPeopleResponse(int added) {
}
package net.officefloor.hq.app.person;

import jakarta.servlet.http.HttpServletRequest;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Adds a person per imported line, in order. Every line is checked first, as the person form checks a
 * person (their name unused on the sheet and its tree, their contact unused on the sheet), and a name or
 * contact repeated within the import is refused too, so a refused import writes nothing; then each
 * person is saved and audited as one added by the form: PERSON_ADDED, then the figures it moved.
 */
public class AddImportedPeople {
    public void add(@Val Sheet sheet, @Val ImportPeopleLines lines, PersonRepository people, SheetRepository sheets,
            ClaimRepository claims, RateRepository rates, SettingsRepository settings, HttpServletRequest request,
            Audit audit, Out<ImportPeopleResponse> result)
            throws DuplicatePersonNameException, DuplicatePersonContactException {
        List<Person> built = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        for (PersonRequest line : lines.lines()) {
            Person person = new Person(null, sheet.id(), line.name(), line.grade());
            person.setTerms(line.termsDays());
            person.setContact(line.contactValue());
            if (!names.add(person.getName().toLowerCase(Locale.ROOT))) {
                throw new DuplicatePersonNameException(person.getName());
            }
            if (person.getContact() != null && !contacts.add(person.getContact())) {
                throw new DuplicatePersonContactException(person.getContact());
            }
            new CheckPersonName().check(person, people, sheets);
            new CheckPersonContact().check(person, people);
            built.add(person);
        }
        String user = Audit.user(request);
        Rollup before = Rollup.of(sheet.id(), sheet.today(), people, claims, rates, settings.find(sheet.id()));
        for (Person person : built) {
            people.save(person);
            new AuditPersonAdded().audit(sheet, person, request, audit);
            Rollup after = Rollup.of(sheet.id(), sheets.today(sheet.id()), people, claims, rates,
                    settings.find(sheet.id()));
            after.changesSince(before, sheet.id(), user).forEach(audit::record);
            before = after;
        }
        result.set(new ImportPeopleResponse(built.size()));
    }
}
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Splits the import into lines (blank lines skipped) and checks each by the person form's rules; the
 * first line that fails refuses the whole import. An import with no lines is refused too.
 */
public class ValidateImportPeople {
    public void validate(@RequestBody ImportPeopleRequest request, Out<ImportPeopleLines> linesOut)
            throws InvalidPersonException {
        String text = request == null || request.text() == null ? "" : request.text();
        List<PersonRequest> lines = new ArrayList<>();
        int number = 0;
        for (String raw : text.split("\\r?\\n|\\r")) {
            number++;
            if (raw.isBlank()) continue;
            String[] fields = raw.split(",", 4);
            if (fields.length < 2) throw new InvalidPersonException("Line " + number + ": name,grade,terms,contact");
            String terms = fields.length > 2 ? fields[2] : "";
            String contact = fields.length > 3 ? fields[3] : "";
            try {
                lines.add(PersonRequest.checked(new PersonRequest(fields[0], fields[1], null, "", terms, contact)));
            } catch (InvalidPersonException e) {
                throw new InvalidPersonException("Line " + number + ": " + e.getMessage());
            }
        }
        if (lines.isEmpty()) throw new InvalidPersonException("Paste at least one line of name,grade,terms,contact");
        linesOut.set(new ImportPeopleLines(lines));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithImportPeople {
    public void respond(@Val ImportPeopleResponse result, ObjectResponse<ImportPeopleResponse> response) {
        response.send(result);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/** Records the saved person, with the grade in force on the sheet's today, and their terms and contact when the edit changed them. Runs after every rule has passed, so a refused change writes nothing. */
public class AuditPersonEdited {
    public void audit(@Val Sheet sheet, @Val Person person, @Val TermsEdit termsEdit, @Val ContactEdit contactEdit,
            HttpServletRequest request, Audit audit) {
        audit.record("PERSON_EDITED sheet=" + sheet.id() + " by=" + Audit.user(request)
                + " name=" + person.getName() + " grade=" + person.gradeOn(sheet.today())
                + (termsEdit.changed() ? " terms=" + (person.getTerms() == null ? "" : person.getTerms()) : "")
                + (contactEdit.changed() ? " contact=" + (person.getContact() == null ? "" : person.getContact()) : ""));
    }
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useUser } from '../session/session';
import { peopleKey } from '../people/people';

type Result = { added: number };

// The import box: lines of name,grade,terms,contact (the terms and contact may be absent or blank)
// each add a person, in order, as the person form would. The server checks every line by the form's
// rules first (a name or contact repeated within the import is refused too): one bad line refuses the
// whole import and adds nothing. The box shows how many were added; the count is cleared while it runs.
function ImportPeople({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');
  const [result, setResult] = useState<Result | null>(null);
  const [error, setError] = useState('');
  const [user] = useUser();

  const once = useOnce();
  const importPeople = useMutation({
    mutationFn: (body: { text: string }) =>
      postJson<Result>(`/api/sheets/${encodeURIComponent(sheetId)}/people/import`, body, user),
    onSuccess: (r) => {
      setResult(r);
      setText('');
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onError: () => setError('Those people could not be imported: check every line.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setResult(null);
    setError('');
    if (text.trim() === '') {
      setError('Paste at least one line of name,grade,terms,contact.');
      return;
    }
    once((done) => importPeople.mutate({ text }, { onSettled: done }));
  };

  return (
    <section data-testid="import-box">
      <form onSubmit={submit}>
        <label>
          Import people (name,grade,terms,contact){' '}
          <textarea
            data-testid="import-people"
            rows={4}
            value={text}
            onChange={(e) => {
              setText(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="import-submit" disabled={importPeople.isPending}>
          Import people
        </button>
        {result !== null && (
          <>
            {' '}Added <span data-testid="import-added">{result.added}</span>
          </>
        )}
        {error && (
          <p role="alert" data-testid="import-error">
            {error}
          </p>
        )}
      </form>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 1.4, Component: ImportPeople });

